58	// ─── sendMessageAction ────────────────────────────────────────────────────────
59	
60	const SendMessageSchema = z.object({
61	  conversationId: z.string().uuid(),
62	  clientId: z.string().uuid(),
63	  body: z.string().min(1).max(1600),
64	  channel: z.enum(['sms', 'email']),
65	  subject: z.string().max(200).optional(),
66	})
67	
68	export async function sendMessageAction(
69	  input: z.infer<typeof SendMessageSchema>,
70	): Promise<ActionResult<{ commId: string }>> {
71	  const authUser = await getAuthenticatedUser()
72	  if (!authUser) return { ok: false, error: 'Unauthorized' }
73	
74	  const parsed = SendMessageSchema.safeParse(input)
75	  if (!parsed.success) {
76	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
77	  }
78	
79	  const { conversationId, clientId, body, channel, subject } = parsed.data
80	  const { studioId } = authUser
81	
82	  try {
83	    if (channel === 'sms') {
84	      const result = await sendSmsToClient(
85	        { studioId, clientId, body },
86	        authUser.user.id,
87	      )
88	      if (!result.ok) {
89	        return { ok: false, error: result.error ?? 'Failed to send SMS' }
90	      }
91	      revalidateMessages()
92	      return { ok: true, data: { commId: result.commId ?? '' } }
93	    }
94	
95	    if (channel === 'email') {
96	      const result = await sendEmailToClient(
97	        {
98	          studioId,
99	          clientId,
100	          subject: subject ?? '(no subject)',
101	          body,
102	        },
103	        authUser.user.id,
104	      )
105	      if (!result.ok) {
106	        return { ok: false, error: result.error ?? 'Failed to send email' }
107	      }
108	      revalidateMessages()
109	      return { ok: true, data: { commId: result.commId ?? '' } }
110	    }
111	
112	    return { ok: false, error: 'Unsupported channel' }
113	  } catch (err) {
114	    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
115	    return { ok: false, error: 'Failed to send message' }
116	  }
117	}
