171	export async function scheduleSendAction(
172	  input: z.infer<typeof ScheduleSendSchema>,
173	): Promise<ActionResult<{ commId: string }>> {
174	  const authUser = await getAuthenticatedUser()
175	  if (!authUser) return { ok: false, error: 'Unauthorized' }
176	
177	  const parsed = ScheduleSendSchema.safeParse(input)
178	  if (!parsed.success) {
179	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
180	  }
181	
182	  try {
183	    const { commId } = await scheduleMessage(authUser.studioId, {
184	      conversationId: parsed.data.conversationId,
185	      clientId: parsed.data.clientId,
186	      body: parsed.data.body,
187	      channel: parsed.data.channel,
188	      scheduledFor: parsed.data.scheduledFor,
