267	// ─── fireSmartReplyAction ─────────────────────────────────────────────────────
268	
269	const FireSmartReplySchema = z.object({
270	  conversationId: z.string().uuid(),
271	  action: z.discriminatedUnion('kind', [
272	    z.object({ kind: z.literal('send_template'), templateSlug: z.string().min(1) }),
273	    z.object({ kind: z.literal('open_calendar_reschedule'), bookingId: z.string().uuid() }),
274	    z.object({ kind: z.literal('share_portfolio') }),
275	    z.object({ kind: z.literal('offer_slots'), days: z.union([z.literal(1), z.literal(3), z.literal(7)]) }),
276	    z.object({ kind: z.literal('send_aftercare_pdf') }),
277	    z.object({ kind: z.literal('request_deposit') }),
278	  ]),
279	  clientId: z.string().uuid(),
280	  channel: z.enum(['sms', 'email']).default('sms'),
281	})
282	
283	export async function fireSmartReplyAction(
284	  input: z.infer<typeof FireSmartReplySchema>,
285	): Promise<ActionResult<{ commId?: string | undefined; navigateTo?: string | undefined }>> {
286	  const authUser = await getAuthenticatedUser()
287	  if (!authUser) return { ok: false, error: 'Unauthorized' }
288	
289	  const parsed = FireSmartReplySchema.safeParse(input)
290	  if (!parsed.success) {
291	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
292	  }
293	
294	  const { conversationId, action, clientId, channel } = parsed.data
295	  const { studioId } = authUser
296	
297	  try {
298	    // Navigation actions — return route for client-side navigation
299	    if (action.kind === 'open_calendar_reschedule') {
300	      return {
301	        ok: true,
302	        data: { navigateTo: `/calendar?rescheduleBooking=${action.bookingId}` },
303	      }
304	    }
305	
306	    // Slot-offer action — render placeholder from template
307	    if (action.kind === 'offer_slots') {
308	      const templates = await listMessageTemplates(studioId, { category: 'reschedule' })
309	      const tpl = templates[0]
310	      if (!tpl) {
311	        return { ok: false, error: 'Reschedule template not found. Add one in Settings → Messaging.' }
312	      }
313	      const result = await sendSmsToClient(
314	        { studioId, clientId, body: tpl.body },
315	        authUser.user.id,
316	      )
317	      if (!result.ok) return { ok: false, error: result.error }
318	      revalidateMessages()
319	      return { ok: true, data: { commId: result.commId } }
320	    }
321	
322	    // Template-based actions — map slug to send
323	    let templateSlug: string | null = null
324	
325	    if (action.kind === 'send_template') {
326	      templateSlug = action.templateSlug
327	    } else if (action.kind === 'send_aftercare_pdf') {
328	      templateSlug = 'aftercare-guide'
329	    } else if (action.kind === 'request_deposit') {
330	      templateSlug = 'deposit-request'
331	    } else if (action.kind === 'share_portfolio') {
332	      templateSlug = 'portfolio-share'
333	    }
334	
335	    if (!templateSlug) {
336	      return { ok: false, error: 'Unknown smart reply action' }
337	    }
338	
339	    const templates = await listMessageTemplates(studioId)
340	    const tpl = templates.find((t) => t.slug === templateSlug)
341	
342	    if (!tpl) {
343	      return { ok: false, error: `Template '${templateSlug}' not found. Check Settings → Messaging.` }
344	    }
345	
346	    let result: Awaited<ReturnType<typeof sendSmsToClient>>
347	
348	    if (channel === 'email') {
349	      result = await sendEmailToClient(
350	        { studioId, clientId, subject: tpl.name, body: tpl.body },
351	        authUser.user.id,
352	      )
353	    } else {
354	      result = await sendSmsToClient(
355	        { studioId, clientId, body: tpl.body },
356	        authUser.user.id,
357	      )
358	    }
359	
360	    if (!result.ok) return { ok: false, error: result.error }
361	
362	    revalidateMessages()
363	    return { ok: true, data: { commId: result.commId } }
364	  } catch (err) {
365	    logger.error({ err, conversationId }, 'fireSmartReplyAction: unexpected error')
366	    return { ok: false, error: 'Failed to send smart reply' }
367	  }
368	}
