'use client'

/**
 * TriageTagPill — inline pill displaying conversation triage tag.
 * All colors use 4-color token system (Bone/Onyx/Stone/Rust only).
 * Returns null when tag is null.
 */

import { cn } from '@/lib/utils'
import type { TriageTag } from '@/lib/supabase/types'

interface TriageTagPillProps {
  tag: TriageTag | null | undefined
  className?: string | undefined
}

interface TagStyle {
  cls: string
  label: string
  dot?: boolean | undefined
  glyph?: string | undefined
}

const TAG_STYLES: Record<TriageTag, TagStyle> = {
  inquiry: {
    cls: 'bg-[color-mix(in_srgb,var(--color-rust)_12%,transparent)] text-[color:var(--color-rust)]',
    label: 'INQUIRY',
  },
  booking: {
    cls: 'bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground',
    label: 'BOOKING',
  },
  client: {
    cls: 'bg-[color-mix(in_srgb,var(--color-stone)_14%,transparent)] text-[color:var(--color-stone)]',
    label: 'CLIENT',
  },
  deposit_paid: {
    cls: 'bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground',
    label: 'DEPOSIT PAID',
    dot: true,
  },
  rescheduling: {
    cls: 'bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground',
    label: 'RESCHEDULING',
    glyph: '↻',
  },
  pricing: {
    cls: 'bg-[color-mix(in_srgb,var(--color-rust)_8%,transparent)] text-[color:var(--color-rust)]',
    label: 'PRICING',
  },
  missed_call: {
    cls: 'bg-[color-mix(in_srgb,var(--color-rust)_16%,transparent)] text-[color:var(--color-rust)]',
    label: 'MISSED CALL',
  },
}

export function TriageTagPill({ tag, className }: TriageTagPillProps) {
  if (!tag) return null

  const style = TAG_STYLES[tag]
  if (!style) return null

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-[0.08em] shrink-0',
        style.cls,
        className,
      )}
    >
      {style.glyph && <span aria-hidden>{style.glyph}</span>}
      {style.label}
      {style.dot && (
        <span
          className="w-1 h-1 rounded-full bg-[color:var(--color-rust)]"
          aria-hidden
        />
      )}
    </span>
  )
}

'use client'

/**
 * ChannelRail — vertical 72px left rail with 7 channel slots.
 *
 * Active channel: Rust 2px left border + accent bg.
 * Disconnected channels: Stone text, opens ConnectChannelSheet on click.
 * Unread badge: absolute top-right on each slot.
 */

import { useRouter, useSearchParams } from 'next/navigation'
import { useState } from 'react'
import { Inbox, MessageSquare, Mail, Instagram, MessageCircle, Globe, Phone } from 'lucide-react'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { ConnectChannelSheet } from './ConnectChannelSheet'
import type { Channel } from '@/lib/messaging/queries'

// ─── Channel config ────────────────────────────────────────────────────────────

type ChannelKey = Channel | 'all'

interface ChannelSlot {
  key: ChannelKey
  label: string
  icon: React.ElementType
  connected: boolean
}

const CHANNELS: ChannelSlot[] = [
  { key: 'all', label: 'ALL', icon: Inbox, connected: true },
  { key: 'sms', label: 'SMS', icon: MessageSquare, connected: true },
  { key: 'email', label: 'EMAIL', icon: Mail, connected: true },
  { key: 'instagram', label: 'IG', icon: Instagram, connected: false },
  { key: 'whatsapp', label: 'WA', icon: MessageCircle, connected: false },
  { key: 'webchat', label: 'CHAT', icon: Globe, connected: false },
  { key: 'phone', label: 'CALL', icon: Phone, connected: false },
]

// ─── Props ─────────────────────────────────────────────────────────────────────

interface ChannelRailProps {
  unreadCounts: Record<Channel, number>
  currentChannel: string | null
}

// ─── ChannelRail ──────────────────────────────────────────────────────────────

export function ChannelRail({ unreadCounts, currentChannel }: ChannelRailProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [connectSheet, setConnectSheet] = useState<Channel | null>(null)

  const activeKey: ChannelKey = (currentChannel as ChannelKey) ?? 'all'

  function handleClick(slot: ChannelSlot) {
    if (!slot.connected && slot.key !== 'all') {
      setConnectSheet(slot.key as Channel)
      return
    }

    const params = new URLSearchParams(searchParams.toString())
    // Remove active conversation when switching channels
    params.delete('c')

    if (slot.key === 'all') {
      params.delete('channel')
    } else {
      params.set('channel', slot.key)
    }

    router.push(`/messages?${params.toString()}`)
  }

  function getUnreadForSlot(key: ChannelKey): number {
    if (key === 'all') {
      return Object.values(unreadCounts).reduce((sum, n) => sum + n, 0)
    }
    return unreadCounts[key as Channel] ?? 0
  }

  return (
    <>
      <div
        className="w-[72px] shrink-0 flex flex-col bg-background border-r border-border"
        role="navigation"
        aria-label="Message channels"
      >
        {CHANNELS.map((slot) => {
          const Icon = slot.icon
          const isActive = slot.key === activeKey || (slot.key === 'all' && !currentChannel)
          const unread = getUnreadForSlot(slot.key)
          const isConnected = slot.connected
          const isDisconnected = !isConnected && slot.key !== 'all'

          return (
            <Tooltip key={slot.key}>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={() => handleClick(slot)}
                  aria-label={isDisconnected ? `Connect ${slot.label}` : `Filter by ${slot.label}`}
                  aria-pressed={isActive}
                  className={cn(
                    'relative w-full h-14 flex flex-col items-center justify-center gap-0.5 transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset',
                    isActive && 'bg-accent',
                    !isActive && isConnected && 'hover:bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)]',
                    !isActive && isDisconnected && 'hover:bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)] cursor-pointer',
                    isActive && 'before:absolute before:left-0 before:top-2 before:bottom-2 before:w-[2px] before:bg-[color:var(--color-rust)] before:rounded-r-full before:content-[""]',
                  )}
                >
                  <Icon
                    className={cn(
                      'h-5 w-5',
                      isActive
                        ? 'text-foreground'
                        : isDisconnected
                          ? 'text-[color:var(--color-stone)]'
                          : 'text-foreground/70',
                    )}
                    aria-hidden
                  />
                  <span
                    className={cn(
                      'text-[10px] font-bold uppercase tracking-[0.08em] leading-none',
                      isActive
                        ? 'text-foreground'
                        : isDisconnected
                          ? 'text-[color:var(--color-stone)]'
                          : 'text-foreground/60',
                    )}
                  >
                    {slot.label}
                  </span>

                  {/* Unread badge */}
                  {unread > 0 && (
                    <span
                      className="absolute top-1.5 right-1.5 min-w-[18px] h-[18px] rounded-full bg-foreground text-background text-[10px] font-bold flex items-center justify-center px-1"
                      aria-label={`${unread} unread`}
                    >
                      {unread > 99 ? '99+' : unread}
                    </span>
                  )}
                </button>
              </TooltipTrigger>
              {isDisconnected && (
                <TooltipContent side="right">Connect {slot.label}</TooltipContent>
              )}
            </Tooltip>
          )
        })}
      </div>

      {/* Connect channel sheet */}
      {connectSheet && (
        <ConnectChannelSheet
          channel={connectSheet}
          open={connectSheet !== null}
          onClose={() => setConnectSheet(null)}
        />
      )}
    </>
  )
}

'use client'

/**
 * ConversationListItem — single row in the conversation list.
 *
 * Layout:
 *   [Avatar+ChannelBadge] [Name + Timestamp]
 *                         [Preview + TriagePill + UnreadDot]
 */

import { formatDistanceToNow } from 'date-fns'
import { Star } from 'lucide-react'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { cn } from '@/lib/utils'
import { TriageTagPill } from './TriageTagPill'
import { ChannelIcon } from './ChannelIcon'
import type { ConversationWithClient } from '@/lib/messaging/queries'

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .filter(Boolean)
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function getDisplayName(conv: ConversationWithClient): string {
  if (conv.display_name) return conv.display_name
  if (conv.client) {
    const { first_name, last_name } = conv.client
    return last_name ? `${first_name} ${last_name}` : first_name
  }
  return conv.external_identifier
}

function formatRelativeTime(dateStr: string | null): string | null {
  if (!dateStr) return null
  try {
    return formatDistanceToNow(new Date(dateStr), { addSuffix: false })
  } catch {
    return null
  }
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ConversationListItemProps {
  conv: ConversationWithClient
  isActive: boolean
  onClick: () => void
}

// ─── Component ────────────────────────────────────────────────────────────────

export function ConversationListItem({ conv, isActive, onClick }: ConversationListItemProps) {
  const displayName = getDisplayName(conv)
  const initials = getInitials(displayName)
  const hasUnread = conv.unread_count > 0
  const relativeTime = formatRelativeTime(conv.last_message_at)
  const triageTag = conv.triage_tag ?? null
  const isMissedCall = triageTag === 'missed_call'

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'w-full text-left px-3 py-3 flex items-start gap-3 transition-colors relative',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset',
        // Default bg
        !isActive && !hasUnread && 'hover:bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)]',
        // Unread row: faint Rust tint
        !isActive && hasUnread && [
          'bg-[color-mix(in_srgb,var(--color-rust)_3%,transparent)]',
          'hover:bg-[color-mix(in_srgb,var(--color-rust)_6%,transparent)]',
        ],
        // Active row: Onyx tint + left border
        isActive && [
          'bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
          'border-l-2',
          isMissedCall ? 'border-[color:var(--color-rust)]' : 'border-primary',
          'pl-[10px]', // compensate for 2px border
        ],
      )}
      aria-current={isActive ? 'page' : undefined}
    >
      {/* Avatar with channel badge */}
      <div className="relative shrink-0 mt-0.5">
        <Avatar className="h-10 w-10">
          <AvatarFallback className="text-xs font-medium bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground">
            {initials}
          </AvatarFallback>
        </Avatar>
        {/* Channel badge — bottom-right of avatar */}
        <span
          className="absolute -bottom-0.5 -right-0.5 w-4.5 h-4.5 rounded-full bg-background border border-border flex items-center justify-center"
          aria-hidden
        >
          <ChannelIcon
            channel={conv.channel as 'sms' | 'email' | 'instagram' | 'whatsapp' | 'webchat' | 'phone'}
            className="h-2.5 w-2.5 text-[color:var(--color-stone)]"
          />
        </span>
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        {/* Line 1: name + timestamp */}
        <div className="flex items-center justify-between gap-2 mb-0.5">
          <span
            className={cn(
              'text-sm truncate',
              hasUnread ? 'font-semibold text-foreground' : 'font-medium text-foreground/80',
            )}
          >
            {displayName}
          </span>
          <div className="flex items-center gap-1 shrink-0">
            {conv.starred && (
              <Star
                className="h-2.5 w-2.5 text-[color:var(--color-rust)] fill-[color:var(--color-rust)]"
                aria-label="Starred"
              />
            )}
            {relativeTime && (
              <span className="text-[11px] text-[color:var(--color-stone)] whitespace-nowrap">
                {relativeTime}
              </span>
            )}
          </div>
        </div>

        {/* Line 2: preview + triage pill + unread dot */}
        <div className="flex items-center gap-1.5 min-w-0">
          <p
            className={cn(
              'text-xs truncate flex-1 min-w-0',
              hasUnread ? 'text-foreground/80' : 'text-[color:var(--color-stone)]',
            )}
          >
            {conv.last_message_preview ?? conv.external_identifier}
          </p>

          {triageTag && <TriageTagPill tag={triageTag} />}

          {/* Unread dot */}
          {hasUnread && (
            <span
              className="w-2 h-2 rounded-full bg-[color:var(--color-rust)] shrink-0"
              aria-label={`${conv.unread_count} unread`}
            />
          )}
        </div>
      </div>
    </button>
  )
}

'use client'

/**
 * ConversationList — 360px left panel listing conversations.
 *
 * Features:
 * - Search input (/ focus hotkey)
 * - Filter pills: All / Unread / Starred / Archived
 * - Realtime conversation list reconciliation
 * - Empty states (zero-state vs filter-zero)
 * - URL-driven state (?channel=, ?filter=, ?q=)
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { Search, Inbox, Star, Archive } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { cn } from '@/lib/utils'
import { useRealtimeConversationList } from '@/hooks/use-realtime-messages'
import { useDebounce } from '@/hooks/useDebounce'
import { ConversationListItem } from './ConversationListItem'
import { EmptyRail } from './EmptyRail'
import type { ConversationWithClient } from '@/lib/messaging/queries'
import type { Conversation } from '@/lib/supabase/types'

// ─── Filter pill config ────────────────────────────────────────────────────────

type FilterKey = 'all' | 'unread' | 'starred' | 'archived'

const FILTER_PILLS: { key: FilterKey; label: string; icon: React.ReactNode }[] = [
  { key: 'all', label: 'All', icon: <Inbox className="h-3 w-3" aria-hidden /> },
  { key: 'unread', label: 'Unread', icon: null },
  { key: 'starred', label: 'Starred', icon: <Star className="h-3 w-3" aria-hidden /> },
  { key: 'archived', label: 'Archived', icon: <Archive className="h-3 w-3" aria-hidden /> },
]

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getDisplayName(conv: ConversationWithClient): string {
  if (conv.display_name) return conv.display_name
  if (conv.client) {
    const { first_name, last_name } = conv.client
    return last_name ? `${first_name} ${last_name}` : first_name
  }
  return conv.external_identifier
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ConversationListProps {
  conversations: ConversationWithClient[]
  studioId: string
  activeConversationId: string | null
}

// ─── ConversationList ─────────────────────────────────────────────────────────

export function ConversationList({
  conversations: initialConversations,
  studioId,
  activeConversationId,
}: ConversationListProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const searchInputRef = useRef<HTMLInputElement>(null)

  const currentFilter = (searchParams.get('filter') as FilterKey) ?? 'all'
  const currentChannel = searchParams.get('channel')

  const [convs, setConvs] = useState<ConversationWithClient[]>(initialConversations)
  const [searchRaw, setSearchRaw] = useState('')
  const search = useDebounce(searchRaw, 300)

  // Keep list in sync when server re-renders
  useEffect(() => {
    setConvs(initialConversations)
  }, [initialConversations])

  // Realtime reconciliation
  const handleConversationUpdate = useCallback((updated: Conversation) => {
    setConvs((prev) =>
      prev
        .map((c) => (c.id === updated.id ? { ...c, ...updated } : c))
        .sort((a, b) => {
          const aTime = a.last_message_at ?? a.created_at
          const bTime = b.last_message_at ?? b.created_at
          return new Date(bTime).getTime() - new Date(aTime).getTime()
        }),
    )
  }, [])

  useRealtimeConversationList(studioId, handleConversationUpdate)

  // Filter logic
  const filtered = convs.filter((c) => {
    // Status filter
    if (currentFilter === 'unread' && c.unread_count === 0) return false
    if (currentFilter === 'starred' && !c.starred) return false
    if (currentFilter === 'archived' && !c.archived_at) return false
    if (currentFilter !== 'archived' && c.archived_at) return false

    // Search
    if (search) {
      const q = search.toLowerCase()
      const name = getDisplayName(c).toLowerCase()
      const ext = c.external_identifier.toLowerCase()
      if (!name.includes(q) && !ext.includes(q)) return false
    }

    return true
  })

  function handleFilterChange(key: FilterKey) {
    const params = new URLSearchParams(searchParams.toString())
    if (key === 'all') {
      params.delete('filter')
    } else {
      params.set('filter', key)
    }
    router.push(`/messages?${params.toString()}`)
  }

  function handleClearFilter() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('filter')
    params.delete('channel')
    router.push(`/messages?${params.toString()}`)
  }

  function handleConversationClick(conv: ConversationWithClient) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('c', conv.id)
    router.push(`/messages?${params.toString()}`)
  }

  // Keyboard: / focuses search
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement).tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA') {
        if (e.key === 'Escape') searchInputRef.current?.blur()
        return
      }
      if (e.key === '/') {
        e.preventDefault()
        searchInputRef.current?.focus()
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  const isFiltered = currentFilter !== 'all' || !!currentChannel || !!search
  const hasAnyConversations = convs.length > 0

  return (
    <div className="w-[360px] shrink-0 flex flex-col h-full border-r border-border bg-background overflow-hidden">
      {/* Header */}
      <div className="px-4 pt-4 pb-3 shrink-0 border-b border-border">
        <h2 className="font-serif italic text-foreground text-base mb-3">Messages</h2>
        {/* Search */}
        <div className="relative">
          <Search
            className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[color:var(--color-stone)] pointer-events-none"
            aria-hidden
          />
          <Input
            ref={searchInputRef}
            placeholder="Search… (/)"
            value={searchRaw}
            onChange={(e) => setSearchRaw(e.target.value)}
            className="pl-8 h-8 text-sm"
            aria-label="Search conversations"
          />
        </div>
      </div>

      {/* Filter pills */}
      <div className="px-3 py-2 flex gap-1 shrink-0 border-b border-border">
        {FILTER_PILLS.map((pill) => {
          const isActive = currentFilter === pill.key
          return (
            <button
              key={pill.key}
              type="button"
              onClick={() => handleFilterChange(pill.key)}
              className={cn(
                'inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
                isActive
                  ? 'bg-primary text-primary-foreground'
                  : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
              )}
              aria-pressed={isActive}
            >
              {pill.icon}
              {pill.label}
            </button>
          )
        })}
      </div>

      {/* Conversation list */}
      <ScrollArea className="flex-1 min-h-0">
        {!hasAnyConversations ? (
          <EmptyRail isFiltered={false} />
        ) : filtered.length === 0 ? (
          <EmptyRail isFiltered={isFiltered} onClearFilter={handleClearFilter} />
        ) : (
          <div role="listbox" aria-label="Conversations" className="py-1">
            {filtered.map((conv) => (
              <ConversationListItem
                key={conv.id}
                conv={conv}
                isActive={conv.id === activeConversationId}
                onClick={() => handleConversationClick(conv)}
              />
            ))}
          </div>
        )}
      </ScrollArea>
    </div>
  )
}

