/**
 * MessageBubble — renders a single message.
 *
 * Variants:
 * - inbound:       left-aligned, Onyx 4% bg
 * - outbound:      right-aligned, Onyx bg (bg-primary)
 * - auto-reply:    inbound shape + Rust 6% tint + "Auto-sent" caption
 * - internal note: full-width centered block, Stone dashed border
 *
 * Status icons (outbound only): queued/sent/delivered/failed
 */

import { format } from 'date-fns'
import { Clock, Check, CheckCheck, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { ConversationMessage } from '@/lib/messaging/queries'

// ─── Helpers ──────────────────────────────────────────────────────────────────

function StatusIcon({ status }: { status: ConversationMessage['status'] }) {
  switch (status) {
    case 'queued':
      return <Clock className="h-3 w-3 text-[color:var(--color-stone)]" aria-label="Queued" />
    case 'sent':
      return <Check className="h-3 w-3 text-[color:var(--color-stone)]" aria-label="Sent" />
    case 'delivered':
    case 'opened':
    case 'clicked':
      return <CheckCheck className="h-3 w-3 text-[color:var(--color-stone)]" aria-label="Delivered" />
    case 'failed':
    case 'bounced':
      return <AlertCircle className="h-3 w-3 text-[color:var(--color-rust)]" aria-label="Failed" />
    default:
      return null
  }
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface MessageBubbleProps {
  message: ConversationMessage
  /** Tighter top spacing when same sender follows consecutively */
  isGrouped?: boolean | undefined
}

// ─── Component ────────────────────────────────────────────────────────────────

export function MessageBubble({ message: msg, isGrouped }: MessageBubbleProps) {
  const isInternalNote = msg.is_internal_note
  const isOutbound = msg.direction === 'outbound' && !isInternalNote
  const isAutoReply =
    !isInternalNote &&
    msg.direction === 'outbound' &&
    typeof msg.metadata === 'object' &&
    msg.metadata !== null &&
    (msg.metadata as Record<string, unknown>)['auto_reply'] === true
  const isOptimistic = msg.id.startsWith('optimistic-')

  const formattedTime = (() => {
    try {
      return format(new Date(msg.created_at), 'h:mm a')
    } catch {
      return ''
    }
  })()

  // ── Internal note ──────────────────────────────────────────────────────────
  if (isInternalNote) {
    return (
      <div className={cn('flex justify-center w-full', isGrouped ? 'mt-1' : 'mt-3')}>
        <div className="max-w-[72ch] w-full mx-auto px-4 py-3 bg-[color-mix(in_srgb,var(--color-stone)_12%,transparent)] border border-dashed border-[color:var(--color-stone)] rounded-lg">
          <span className="block text-[10px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-1.5">
            Staff only
          </span>
          <p className="text-sm text-foreground whitespace-pre-wrap break-words">{msg.body}</p>
          {!isGrouped && (
            <p className="text-[11px] text-[color:var(--color-stone)] mt-1.5">{formattedTime}</p>
          )}
        </div>
      </div>
    )
  }

  // ── Auto-reply ─────────────────────────────────────────────────────────────
  if (isAutoReply) {
    return (
      <div className={cn('flex justify-start', isGrouped ? 'mt-1' : 'mt-3')}>
        <div className="max-w-[72ch]">
          {msg.subject && (
            <p className="text-[10px] font-medium text-[color:var(--color-stone)] uppercase tracking-wide mb-1">
              {msg.subject}
            </p>
          )}
          <div className="px-4 py-2.5 bg-[color-mix(in_srgb,var(--color-rust)_6%,transparent)] border border-[color-mix(in_srgb,var(--color-rust)_25%,transparent)] text-foreground rounded-2xl rounded-tl-sm">
            <p className="text-sm whitespace-pre-wrap break-words">{msg.body}</p>
          </div>
          {!isGrouped && (
            <p className="text-[11px] italic text-[color:var(--color-rust)] mt-1">Auto-sent · {formattedTime}</p>
          )}
        </div>
      </div>
    )
  }

  // ── Outbound ───────────────────────────────────────────────────────────────
  if (isOutbound) {
    return (
      <div className={cn('flex justify-end', isGrouped ? 'mt-1' : 'mt-3', isOptimistic && 'opacity-60')}>
        <div className="max-w-[72ch] flex flex-col items-end">
          {msg.subject && (
            <p className="text-[10px] font-medium text-[color:var(--color-stone)] uppercase tracking-wide mb-1">
              {msg.subject}
            </p>
          )}
          <div className="px-4 py-2.5 bg-primary text-primary-foreground rounded-2xl rounded-tr-sm">
            <p className="text-sm whitespace-pre-wrap break-words">{msg.body}</p>
          </div>
          {!isGrouped && (
            <div className="flex items-center gap-1 mt-1">
              <span className="text-[11px] text-[color:var(--color-stone)]">{formattedTime}</span>
              <StatusIcon status={msg.status} />
              {(msg.status === 'failed' || msg.status === 'bounced') && msg.error && (
                <span className="text-[11px] text-[color:var(--color-rust)]">{msg.error}</span>
              )}
            </div>
          )}
        </div>
      </div>
    )
  }

  // ── Inbound ────────────────────────────────────────────────────────────────
  return (
    <div className={cn('flex justify-start', isGrouped ? 'mt-1' : 'mt-3')}>
      <div className="max-w-[72ch]">
        {msg.subject && (
          <p className="text-[10px] font-medium text-[color:var(--color-stone)] uppercase tracking-wide mb-1">
            {msg.subject}
          </p>
        )}
        <div className="px-4 py-2.5 bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)] text-foreground rounded-2xl rounded-tl-sm">
          <p className="text-sm whitespace-pre-wrap break-words">{msg.body}</p>
        </div>
        {!isGrouped && (
          <p className="text-[11px] text-[color:var(--color-stone)] mt-1">{formattedTime}</p>
        )}
      </div>
    </div>
  )
}

