/**
 * PresenceStrip — shows who is viewing or typing in the active conversation.
 * Always occupies min-h to prevent layout shift.
 * Typing animation: 3 Stone dots with staggered pulse.
 */

import { cn } from '@/lib/utils'

export interface PresenceUser {
  userId: string
  userName: string
  state: 'viewing' | 'typing'
}

interface PresenceStripProps {
  viewers: PresenceUser[]
  typing: PresenceUser[]
}

function formatNames(users: PresenceUser[]): string {
  const names = users.map((u) => u.userName)
  if (names.length === 0) return ''
  if (names.length === 1) return names[0] ?? ''
  if (names.length === 2) return `${names[0]} and ${names[1]}`
  return `${names[0]}, ${names[1]} and ${names.length - 2} more`
}

export function PresenceStrip({ viewers, typing }: PresenceStripProps) {
  const hasTyping = typing.length > 0
  const hasViewers = viewers.length > 0
  const hasAny = hasTyping || hasViewers

  return (
    <div className="px-4 py-1.5 min-h-[28px] flex items-center gap-2">
      {hasAny && (
        <p className="text-[13px] italic text-[color:var(--color-stone)] flex items-center gap-1.5">
          {hasTyping ? (
            <>
              <span>{formatNames(typing)} is typing</span>
              {/* 3-dot typing indicator */}
              <span className="flex items-center gap-0.5" aria-hidden>
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '0ms' }}
                />
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '200ms' }}
                />
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '400ms' }}
                />
              </span>
            </>
          ) : hasViewers ? (
            <span>{formatNames(viewers)} is viewing</span>
          ) : null}
        </p>
      )}
    </div>
  )
}

