/**
 * SmartReplyChips — horizontal scrollable chip row of smart reply suggestions.
 * Each chip fires a SmartReplyAction when clicked.
 */

import { useTransition } from 'react'
import { Sparkles } from 'lucide-react'
import { toast } from 'sonner'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { fireSmartReplyAction } from '@/app/(app)/messages/actions'
import type { SmartReply } from '@/lib/messaging/triage'

interface SmartReplyChipsProps {
  replies: SmartReply[]
  conversationId: string
  clientId: string
  channel: 'sms' | 'email'
  disabled?: boolean | undefined
}

export function SmartReplyChips({
  replies,
  conversationId,
  clientId,
  channel,
  disabled,
}: SmartReplyChipsProps) {
  const [isPending, startTransition] = useTransition()

  if (replies.length === 0) return null

  function handleFire(reply: SmartReply) {
    if (disabled || isPending) return

    startTransition(async () => {
      const result = await fireSmartReplyAction({
        conversationId,
        action: reply.action,
        clientId,
        channel,
      })

      if (!result.ok) {
        toast.error(result.error ?? 'Failed to send reply')
        return
      }

      if (result.data?.navigateTo) {
        // Navigate to calendar or other page
        window.location.href = result.data.navigateTo
        return
      }

      toast.success('Reply sent')
    })
  }

  return (
    <div
      className="px-4 py-2 flex items-center gap-2 overflow-x-auto"
      role="group"
      aria-label="Smart reply suggestions"
    >
      {replies.map((reply) => {
        const label = reply.label.length > 28 ? reply.label.slice(0, 28) + '…' : reply.label
        const needsTooltip = reply.label.length > 28

        const chip = (
          <button
            key={reply.id}
            type="button"
            onClick={() => handleFire(reply)}
            disabled={disabled || isPending}
            className={cn(
              'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full',
              'border border-border',
              'bg-[color-mix(in_srgb,var(--color-onyx)_3%,transparent)]',
              'hover:bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)]',
              'text-sm whitespace-nowrap transition-colors shrink-0',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              'disabled:opacity-50 disabled:cursor-not-allowed',
            )}
          >
            <Sparkles className="h-3.5 w-3.5 text-[color:var(--color-stone)] shrink-0" aria-hidden />
            <span>{label}</span>
          </button>
        )

        if (needsTooltip) {
          return (
            <Tooltip key={reply.id}>
              <TooltipTrigger asChild>{chip}</TooltipTrigger>
              <TooltipContent side="top">{reply.label}</TooltipContent>
            </Tooltip>
          )
        }

        return chip
      })}
    </div>
  )
}

