/**
 * TemplatePopover — cmdk-powered template picker.
 *
 * Opens via "/" trigger in composer or "Templates" button.
 * Inserts rendered template body into composer.
 * Resolves {{client_first_name}} etc. immediately for preview.
 */

import { useState, useEffect } from 'react'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import type { MessageTemplate } from '@/lib/supabase/types'

// ─── Template token resolver ──────────────────────────────────────────────────

function resolveTokens(body: string, clientFirstName: string | null): string {
  return body
    .replace(/\{\{client_first_name\}\}/g, clientFirstName ?? 'Client')
    .replace(/\{\{studio_name\}\}/g, '')
    .replace(/\{\{booking_link\}\}/g, '[booking link]')
    .replace(/\{\{portfolio_link\}\}/g, '[portfolio link]')
    .replace(/\{\{aftercare_pdf_link\}\}/g, '[aftercare guide]')
    .replace(/\{\{next_available_slot\}\}/g, '[next available]')
}

// Category display labels
const CATEGORY_LABELS: Record<string, string> = {
  aftercare: 'Aftercare',
  deposit: 'Deposit',
  booking: 'Booking',
  portfolio: 'Portfolio',
  reschedule: 'Reschedule',
  inquiry_reply: 'Inquiry reply',
  custom: 'Custom',
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface TemplatePopoverProps {
  templates: MessageTemplate[]
  clientFirstName: string | null
  open: boolean
  onOpenChange: (open: boolean) => void
  onSelect: (body: string) => void
  /** The anchor element — passed from composer */
  children: React.ReactNode
}

// ─── Component ────────────────────────────────────────────────────────────────

export function TemplatePopover({
  templates,
  clientFirstName,
  open,
  onOpenChange,
  onSelect,
  children,
}: TemplatePopoverProps) {
  const [search, setSearch] = useState('')

  // Reset search when popover closes
  useEffect(() => {
    if (!open) setSearch('')
  }, [open])

  // Group templates by category
  const grouped = templates.reduce<Record<string, MessageTemplate[]>>((acc, tpl) => {
    const cat = tpl.category ?? 'custom'
    if (!acc[cat]) acc[cat] = []
    acc[cat]!.push(tpl)
    return acc
  }, {})

  // Order: standard categories first, custom last
  const categoryOrder = ['aftercare', 'deposit', 'booking', 'portfolio', 'reschedule', 'inquiry_reply', 'custom']
  const orderedCategories = categoryOrder.filter((c) => grouped[c]?.length)

  function handleSelect(template: MessageTemplate) {
    const resolved = resolveTokens(template.body, clientFirstName)
    onSelect(resolved)
    onOpenChange(false)
  }

  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent
        side="top"
        align="start"
        className="p-0 w-[360px] shadow-lift"
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <Command>
          <CommandInput
            placeholder="Search templates…"
            value={search}
            onValueChange={setSearch}
            className="h-9"
          />
          <CommandList className="max-h-[320px]">
            <CommandEmpty>
              <p className="text-sm text-[color:var(--color-stone)] py-6 text-center">
                No templates found.
              </p>
            </CommandEmpty>
            {orderedCategories.map((category) => {
              const items = grouped[category] ?? []
              const filteredItems = search
                ? items.filter(
                    (t) =>
                      t.name.toLowerCase().includes(search.toLowerCase()) ||
                      t.body.toLowerCase().includes(search.toLowerCase()),
                  )
                : items

              if (filteredItems.length === 0) return null

              return (
                <CommandGroup key={category} heading={CATEGORY_LABELS[category] ?? category}>
                  {filteredItems.map((tpl) => {
                    const preview = resolveTokens(tpl.body, clientFirstName)
                    const truncatedPreview =
                      preview.length > 60 ? preview.slice(0, 60) + '…' : preview

                    return (
                      <CommandItem
                        key={tpl.id}
                        value={`${tpl.name} ${tpl.body}`}
                        onSelect={() => handleSelect(tpl)}
                        className="flex flex-col items-start gap-0.5 py-2 cursor-pointer"
                      >
                        <span className="text-sm font-semibold text-foreground">{tpl.name}</span>
                        <span className="text-xs text-[color:var(--color-stone)] line-clamp-1">
                          {truncatedPreview}
                        </span>
                      </CommandItem>
                    )
                  })}
                </CommandGroup>
              )
            })}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

/**
 * ScheduleSendPopover — datetime picker for schedule-send.
 * Quick chips + custom datetime-local input.
 */

import { useState } from 'react'
import { Clock } from 'lucide-react'
import { addHours, addDays, nextMonday, setHours, setMinutes } from 'date-fns'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

interface ScheduleSendPopoverProps {
  onSchedule: (scheduledFor: string) => void
  disabled?: boolean | undefined
  children: React.ReactNode
}

interface QuickOption {
  label: string
  getDate: () => Date
}

function toLocalDatetimeInputValue(date: Date): string {
  // datetime-local expects YYYY-MM-DDTHH:mm
  const pad = (n: number) => String(n).padStart(2, '0')
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `T${pad(date.getHours())}:${pad(date.getMinutes())}`
  )
}

export function ScheduleSendPopover({
  onSchedule,
  disabled,
  children,
}: ScheduleSendPopoverProps) {
  const [open, setOpen] = useState(false)
  const [customValue, setCustomValue] = useState('')

  const QUICK_OPTIONS: QuickOption[] = [
    {
      label: 'In 1 hour',
      getDate: () => addHours(new Date(), 1),
    },
    {
      label: 'Tomorrow 9 AM',
      getDate: () => setMinutes(setHours(addDays(new Date(), 1), 9), 0),
    },
    {
      label: 'Next Monday 9 AM',
      getDate: () => setMinutes(setHours(nextMonday(new Date()), 9), 0),
    },
  ]

  function handleQuick(option: QuickOption) {
    const date = option.getDate()
    onSchedule(date.toISOString())
    setOpen(false)
  }

  function handleCustomSubmit() {
    if (!customValue) return
    const date = new Date(customValue)
    if (isNaN(date.getTime())) return
    // Must be in the future
    if (date <= new Date()) return
    onSchedule(date.toISOString())
    setOpen(false)
    setCustomValue('')
  }

  const minDatetime = toLocalDatetimeInputValue(addHours(new Date(), 0.1))

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        {children}
      </PopoverTrigger>
      <PopoverContent
        side="top"
        align="start"
        className="w-[260px] p-3 shadow-lift"
      >
        <p className="text-[10px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-3">
          Schedule send
        </p>

        {/* Quick chips */}
        <div className="flex flex-col gap-1.5 mb-3">
          {QUICK_OPTIONS.map((opt) => (
            <button
              key={opt.label}
              type="button"
              onClick={() => handleQuick(opt)}
              className={cn(
                'text-left px-3 py-1.5 rounded-md text-sm text-foreground',
                'bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)]',
                'hover:bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)]',
                'transition-colors',
              )}
            >
              {opt.label}
            </button>
          ))}
        </div>

        {/* Custom datetime */}
        <div className="border-t border-border pt-3 space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
            Custom
          </label>
          <input
            type="datetime-local"
            value={customValue}
            min={minDatetime}
            onChange={(e) => setCustomValue(e.target.value)}
            className="w-full h-8 px-2 text-sm border border-input rounded-md bg-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            aria-label="Custom schedule date and time"
          />
          <Button
            size="sm"
            className="w-full"
            disabled={!customValue}
            onClick={handleCustomSubmit}
          >
            <Clock className="h-3.5 w-3.5 mr-1.5" aria-hidden />
            Schedule send
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

'use client'

/**
 * Composer — full-featured compose area at the bottom of ThreadPanel.
 *
 * Features:
 * - Channel switcher (SMS / Email)
 * - "/" trigger opens TemplatePopover
 * - Internal-note toggle (changes bg + button label)
 * - Schedule send popover
 * - Optimistic send
 * - ⌘+Enter to send
 */

import { useState, useRef, useCallback, useTransition, useEffect } from 'react'
import { StickyNote, Paperclip, Clock, Command as CommandIcon } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import {
  sendMessageAction,
  sendInternalNoteAction,
  scheduleSendAction,
} from '@/app/(app)/messages/actions'
import type { ConversationMessage } from '@/lib/messaging/queries'
import type { MessageTemplate } from '@/lib/supabase/types'
import { ChannelSwitcher } from './ChannelSwitcher'
import { TemplatePopover } from './TemplatePopover'
import { ScheduleSendPopover } from './ScheduleSendPopover'
import type { Channel } from '@/lib/messaging/queries'

// ─── Props ────────────────────────────────────────────────────────────────────

interface ComposerProps {
  conversationId: string
  clientId: string
  channel: Channel
  clientFirstName?: string | undefined
  clientHasPhone: boolean
  clientHasEmail: boolean
  templates: MessageTemplate[]
  onOptimisticSend: (msg: ConversationMessage) => void
  onInternalNoteModeChange?: ((isInternal: boolean) => void) | undefined
  disabled?: boolean | undefined
}

// ─── Component ────────────────────────────────────────────────────────────────

export function Composer({
  conversationId,
  clientId,
  channel: initialChannel,
  clientFirstName = 'Client',
  clientHasPhone,
  clientHasEmail,
  templates,
  onOptimisticSend,
  onInternalNoteModeChange,
  disabled = false,
}: ComposerProps) {
  const [body, setBody] = useState('')
  const [isInternalNote, setIsInternalNote] = useState(false)
  const [templatePopoverOpen, setTemplatePopoverOpen] = useState(false)
  const [activeChannel, setActiveChannel] = useState<'sms' | 'email'>(
    initialChannel === 'email' ? 'email' : 'sms',
  )
  const [isPending, startTransition] = useTransition()
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  // Keep channel in sync when conversation changes
  useEffect(() => {
    setActiveChannel(initialChannel === 'email' ? 'email' : 'sms')
    setBody('')
    setIsInternalNote(false)
  }, [conversationId, initialChannel])

  // Notify parent when internal-note mode changes
  useEffect(() => {
    onInternalNoteModeChange?.(isInternalNote)
  }, [isInternalNote, onInternalNoteModeChange])

  const autoResize = useCallback((el: HTMLTextAreaElement) => {
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, 240)}px`
  }, [])

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const value = e.target.value
      setBody(value)
      autoResize(e.target)

      // "/" at start of empty line triggers template popover
      if (value === '/' && !isInternalNote) {
        setTemplatePopoverOpen(true)
        setBody('')
      }
    },
    [autoResize, isInternalNote],
  )

  const handleTemplateSelect = useCallback(
    (resolvedBody: string) => {
      setBody(resolvedBody)
      setTimeout(() => {
        const el = textareaRef.current
        if (el) {
          el.focus()
          autoResize(el)
          el.setSelectionRange(resolvedBody.length, resolvedBody.length)
        }
      }, 0)
    },
    [autoResize],
  )

  const handleSend = useCallback(() => {
    const trimmed = body.trim()
    if (!trimmed || isPending || disabled) return

    const optimisticMsg: ConversationMessage = {
      id: `optimistic-${Date.now()}`,
      conversation_id: conversationId,
      channel: (isInternalNote ? 'in_app' : activeChannel) as ConversationMessage['channel'],
      direction: 'outbound',
      subject: null,
      body: trimmed,
      status: 'queued',
      sent_at: null,
      delivered_at: null,
      opened_at: null,
      error: null,
      provider_message_id: null,
      metadata: isInternalNote ? { auto_reply: false } : {},
      is_internal_note: isInternalNote,
      scheduled_for: null,
      reply_to_message_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }

    onOptimisticSend(optimisticMsg)
    setBody('')
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
    }

    startTransition(async () => {
      if (isInternalNote) {
        const result = await sendInternalNoteAction({
          conversationId,
          clientId,
          body: trimmed,
        })
        if (!result.ok) toast.error(result.error ?? 'Failed to save note')
        return
      }

      const result = await sendMessageAction({
        conversationId,
        clientId,
        body: trimmed,
        channel: activeChannel,
      })
      if (!result.ok) toast.error(result.error ?? 'Failed to send message')
    })
  }, [body, isPending, disabled, conversationId, clientId, activeChannel, isInternalNote, onOptimisticSend])

  const handleSchedule = useCallback(
    (scheduledFor: string) => {
      const trimmed = body.trim()
      if (!trimmed || isPending || disabled) return

      startTransition(async () => {
        const result = await scheduleSendAction({
          conversationId,
          clientId,
          body: trimmed,
          channel: activeChannel,
          scheduledFor,
        })
        if (!result.ok) {
          toast.error(result.error ?? 'Failed to schedule message')
          return
        }
        toast.success('Message scheduled')
        setBody('')
        if (textareaRef.current) {
          textareaRef.current.style.height = 'auto'
        }
      })
    },
    [body, isPending, disabled, conversationId, clientId, activeChannel],
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
        e.preventDefault()
        handleSend()
        return
      }
      if (e.key === 'Escape') {
        if (isInternalNote) {
          setIsInternalNote(false)
        } else if (templatePopoverOpen) {
          setTemplatePopoverOpen(false)
        }
      }
    },
    [handleSend, isInternalNote, templatePopoverOpen],
  )

  const canSend = body.trim().length > 0 && !isPending && !disabled
  const isSmsMode = activeChannel === 'sms' && !isInternalNote
  const sendLabel = isInternalNote ? 'Save note' : 'Send'

  return (
    <div
      className={cn(
        'border-t border-border px-3 py-3 transition-colors',
        isInternalNote
          ? 'bg-[color-mix(in_srgb,var(--color-stone)_10%,transparent)] border-dashed border-[color:var(--color-stone)]'
          : 'bg-background',
      )}
    >
      {/* Internal note caption */}
      {isInternalNote && (
        <p className="text-xs italic text-[color:var(--color-stone)] mb-2">
          Staff only — this note stays in the studio.
        </p>
      )}

      {/* Textarea */}
      <div className="relative mb-2">
        <textarea
          ref={textareaRef}
          value={body}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          placeholder={
            isInternalNote
              ? 'Add a staff note…'
              : `Type a ${activeChannel === 'sms' ? 'message' : 'email'}… (/ for templates, ⌘+Enter to send)`
          }
          rows={2}
          disabled={disabled || isPending}
          aria-label={isInternalNote ? 'Internal note body' : 'Message body'}
          className={cn(
            'w-full resize-none border-0 bg-transparent px-1 py-1 text-sm',
            'placeholder:text-[color:var(--color-stone)] focus-visible:outline-none',
            'disabled:opacity-50 disabled:cursor-not-allowed',
            'min-h-[68px] max-h-[240px] overflow-y-auto',
          )}
          style={{ height: 'auto' }}
        />
        {/* SMS char counter */}
        {isSmsMode && body.length > 0 && (
          <span
            className={cn(
              'absolute right-1 bottom-1 text-[10px]',
              body.length > 160 ? 'text-[color:var(--color-rust)]' : 'text-[color:var(--color-stone)]',
            )}
          >
            {body.length}
            {body.length > 160 && ` (${Math.ceil(body.length / 160)} seg)`}
          </span>
        )}
      </div>

      {/* Tools bar */}
      <div className="flex items-center gap-1 flex-wrap">
        {/* Channel switcher */}
        {!isInternalNote && (
          <>
            <ChannelSwitcher
              current={activeChannel}
              hasPhone={clientHasPhone}
              hasEmail={clientHasEmail}
              onChange={setActiveChannel}
              disabled={disabled}
            />
            <Separator orientation="vertical" className="h-5 mx-1" />
          </>
        )}

        {/* Templates button */}
        {!isInternalNote && (
          <TemplatePopover
            templates={templates}
            clientFirstName={clientFirstName ?? null}
            open={templatePopoverOpen}
            onOpenChange={setTemplatePopoverOpen}
            onSelect={handleTemplateSelect}
          >
            <button
              type="button"
              disabled={disabled}
              aria-label="Insert template"
              className="inline-flex items-center gap-1 px-2 py-1 h-7 text-xs font-medium text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
            >
              <CommandIcon className="h-3.5 w-3.5" aria-hidden />
              Templates
            </button>
          </TemplatePopover>
        )}

        {/* Attach (stub) */}
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              disabled={disabled}
              aria-label="Attach file"
              className="inline-flex items-center justify-center h-7 w-7 text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
            >
              <Paperclip className="h-3.5 w-3.5" aria-hidden />
            </button>
          </TooltipTrigger>
          <TooltipContent>Attach file</TooltipContent>
        </Tooltip>

        {/* Internal note toggle */}
        <Tooltip>
          <TooltipTrigger asChild>
            <button
              type="button"
              onClick={() => setIsInternalNote((v) => !v)}
              disabled={disabled}
              aria-label={isInternalNote ? 'Exit staff note mode' : 'Add staff note'}
              aria-pressed={isInternalNote}
              className={cn(
                'inline-flex items-center justify-center h-7 w-7 rounded-md transition-colors disabled:opacity-50',
                isInternalNote
                  ? 'bg-[color-mix(in_srgb,var(--color-stone)_16%,transparent)] text-foreground'
                  : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
              )}
            >
              <StickyNote className="h-3.5 w-3.5" aria-hidden />
            </button>
          </TooltipTrigger>
          <TooltipContent>Staff-only note</TooltipContent>
        </Tooltip>

        {/* Schedule send (hidden in internal-note mode) */}
        {!isInternalNote && (
          <ScheduleSendPopover onSchedule={handleSchedule} disabled={disabled || !canSend}>
            <Tooltip>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  disabled={disabled || !canSend}
                  aria-label="Schedule send"
                  className="inline-flex items-center justify-center h-7 w-7 text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
                >
                  <Clock className="h-3.5 w-3.5" aria-hidden />
                </button>
              </TooltipTrigger>
              <TooltipContent>Schedule send</TooltipContent>
            </Tooltip>
          </ScheduleSendPopover>
        )}

        {/* Spacer */}
        <div className="flex-1" />

        {/* Send button */}
        <Button
          size="sm"
          className="h-7 px-3 text-xs"
          disabled={!canSend}
          onClick={handleSend}
          aria-label={sendLabel}
        >
          {isPending ? (
            <span className="animate-pulse">
              {isInternalNote ? 'Saving…' : 'Sending…'}
            </span>
          ) : (
            sendLabel
          )}
        </Button>
      </div>
    </div>
  )
}

'use client'

/**
