 * Prefer conditional render over CSS max-height animation (stillness is brand).
 */

import { useState } from 'react'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'

interface ContextSectionProps {
  title: string
  defaultOpen?: boolean | undefined
  /** Optional top-right action element */
  action?: React.ReactNode | undefined
  children: React.ReactNode
}

export function ContextSection({
  title,
  defaultOpen = true,
  action,
  children,
}: ContextSectionProps) {
  const [open, setOpen] = useState(defaultOpen)

  return (
    <div className="border-b border-border last:border-0">
      <div className="flex items-center justify-between px-4 py-2.5">
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className="flex items-center gap-1.5 text-left group focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded"
          aria-expanded={open}
        >
          {open ? (
            <ChevronDown className="h-3 w-3 text-[color:var(--color-stone)] shrink-0" aria-hidden />
          ) : (
            <ChevronRight className="h-3 w-3 text-[color:var(--color-stone)] shrink-0" aria-hidden />
