 * 4. Consent forms
 * 5. Reference images
 * 6. Session history
 * 7. Internal notes
 * 8. Quick actions (2×3 grid)
 *
 * When renderAsSheet=true, renders as a Sheet (tablet/mobile).
 */

import Link from 'next/link'
import { format } from 'date-fns'
import {
  X,
  Phone,
  Mail,
  Calendar,
  ExternalLink,
  FileText,
  Image,
  CheckCircle2,
  Clock,
  AlertCircle,
  DollarSign,
} from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'
import { ContextSection } from './ContextSection'
import type { ConversationContext } from '@/lib/messaging/queries'

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(firstName: string, lastName: string | null): string {
  const parts = [firstName, lastName].filter(Boolean)
  return parts
    .map((p) => p![0])
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function formatDate(dateStr: string | null): string {
  if (!dateStr) return '—'
  try {
    return format(new Date(dateStr), 'MMM d, yyyy')
  } catch {
    return '—'
  }
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ContextPaneProps {
  context: ConversationContext
  conversationId: string
  onClose: () => void
  /** Renders inside Sheet instead of grid column */
  renderAsSheet?: boolean | undefined
  sheetOpen?: boolean | undefined
  /** Called from quick actions to toggle internal-note mode in composer */
  onAddNote?: (() => void) | undefined
}

// ─── ContextPaneContent ────────────────────────────────────────────────────────

function ContextPaneContent({
  context,
  conversationId,
  onClose,
  onAddNote,
}: Omit<ContextPaneProps, 'renderAsSheet' | 'sheetOpen'>) {
