                    ))}
                    <Link
                      href={`/clients/${client.id}`}
                      className="text-xs text-[color:var(--color-stone)] hover:text-foreground transition-colors inline-flex items-center gap-1"
                    >
                      View all <ExternalLink className="h-3 w-3" aria-hidden />
                    </Link>
