              </div>
            </ContextSection>

            {/* 7. Internal notes */}
            <ContextSection title="Internal notes" defaultOpen={internalNotes.length > 0}>
              <div className="px-4 space-y-2">
                {internalNotes.length === 0 ? (
                  <p className="text-xs text-[color:var(--color-stone)] italic">No staff notes.</p>
