                  internalNotes.map((note) => (
                    <div
                      key={note.id}
                      className="p-2 bg-[color-mix(in_srgb,var(--color-stone)_10%,transparent)] border border-dashed border-[color:var(--color-stone)] rounded-md"
                    >
                      <p className="text-xs text-foreground whitespace-pre-wrap">{note.body}</p>
                      <p className="text-[10px] text-[color:var(--color-stone)] mt-1">
                        {formatDate(note.created_at)}
                      </p>
                    </div>
                  ))
