                )}
              </div>
            </ContextSection>

            {/* 8. Quick actions */}
            <ContextSection title="Quick actions">
              <div className="px-4 grid grid-cols-2 gap-1.5">
                {[
                  { label: 'Reschedule booking', href: `/calendar` },
                  { label: 'Request payment', href: `/payments` },
                  { label: 'Send consent form', href: `/forms` },
                  { label: 'Share portfolio', href: `/portfolio` },
                  { label: 'Create booking', href: `/bookings/new?clientId=${client.id}` },
                  { label: 'View client', href: `/clients/${client.id}` },
                ].map((action) => (
                  <Link key={action.label} href={action.href}>
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full text-xs h-7 justify-start font-normal truncate"
                    >
                      <span className="truncate">{action.label}</span>
                    </Button>
                  </Link>
                ))}
              </div>
            </ContextSection>
          </div>
        )}
      </ScrollArea>
    </div>
  )
}

