'use client'

/**
 * useConversationPresence — Supabase Realtime presence per conversation.
 *
 * Tracks who is viewing and typing in the active conversation.
 * Excludes the current user from returned arrays.
 * Throttles typing state to 1 send per 2s.
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { PresenceUser } from '@/components/messages/PresenceStrip'

const TYPING_THROTTLE_MS = 2000

function presenceChannelName(conversationId: string): string {
  return `presence:conversation:${conversationId}`
}

interface UseConversationPresenceReturn {
  viewers: PresenceUser[]
  typing: PresenceUser[]
  setTyping: (isTyping: boolean) => void
}

export function useConversationPresence(
  conversationId: string | null,
  currentUserId: string,
  currentUserName: string,
): UseConversationPresenceReturn {
  const [viewers, setViewers] = useState<PresenceUser[]>([])
  const [typing, setTypingState] = useState<PresenceUser[]>([])
  const lastTypingSentAt = useRef<number>(0)
  const channelRef = useRef<ReturnType<ReturnType<typeof createClient>['channel']> | null>(null)

  useEffect(() => {
    if (!conversationId) {
      setViewers([])
      setTypingState([])
      return
    }

    const supabase = createClient()
    const channelName = presenceChannelName(conversationId)

    const ch = supabase.channel(channelName, {
      config: { presence: { key: currentUserId } },
    })

    channelRef.current = ch

    ch.on('presence', { event: 'sync' }, () => {
      const state = ch.presenceState<{ userId: string; userName: string; state: 'viewing' | 'typing' }>()

      const allUsers: PresenceUser[] = Object.values(state).flatMap((presences) =>
        presences.map((p) => ({ userId: p.userId, userName: p.userName, state: p.state })),
      )

      // Exclude current user
      const others = allUsers.filter((u) => u.userId !== currentUserId)

      setViewers(others.filter((u) => u.state === 'viewing'))
      setTypingState(others.filter((u) => u.state === 'typing'))
    })

    ch.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        void ch.track({
          userId: currentUserId,
          userName: currentUserName,
          state: 'viewing',
          ts: Date.now(),
        })
      }
    })

    return () => {
      void supabase.removeChannel(ch)
      channelRef.current = null
    }
  }, [conversationId, currentUserId, currentUserName])

  const setTyping = useCallback(
    (isTyping: boolean) => {
      const ch = channelRef.current
      if (!ch) return

      const now = Date.now()
      if (isTyping && now - lastTypingSentAt.current < TYPING_THROTTLE_MS) return

      lastTypingSentAt.current = now

      void ch.track({
        userId: currentUserId,
        userName: currentUserName,
        state: isTyping ? 'typing' : 'viewing',
        ts: now,
      })
    },
    [currentUserId, currentUserName],
  )

  return { viewers, typing, setTyping }
}

'use client'

/**
 * useSmartReplies — client-side hook that returns smart reply chips.
 *
 * v1: smart replies are computed server-side and passed down as props.
 * This hook just holds the pre-computed list and exposes a setter so
 * the parent can push fresh replies when a new inbound message arrives.
 *
 * The hook signature is forward-compatible with a v2 refetch-on-message
 * implementation using a Server Action call.
 */

import { useState, useCallback } from 'react'
import type { SmartReply } from '@/lib/messaging/triage'

interface UseSmartRepliesReturn {
  replies: SmartReply[]
  setReplies: (replies: SmartReply[]) => void
  clearReplies: () => void
}

export function useSmartReplies(initialReplies: SmartReply[] = []): UseSmartRepliesReturn {
  const [replies, setRepliesState] = useState<SmartReply[]>(initialReplies)

  const setReplies = useCallback((next: SmartReply[]) => {
    setRepliesState(next)
  }, [])

  const clearReplies = useCallback(() => {
    setRepliesState([])
  }, [])

  return { replies, setReplies, clearReplies }
}

'use client'

/**
 * useConversationContext — client-side holder for context pane data.
 *
 * v1: server-rendered context is passed as props; this hook just stores it.
 * The setter allows future realtime invalidation without prop drilling.
 */

import { useState, useEffect } from 'react'
import type { ConversationContext } from '@/lib/messaging/queries'

export function useConversationContext(
  initialContext: ConversationContext | null,
): ConversationContext | null {
  const [context, setContext] = useState<ConversationContext | null>(initialContext)

  // Sync when the server re-renders with new conversation
  useEffect(() => {
    setContext(initialContext)
  }, [initialContext])

  return context
}

'use client'

/**
 * ThreadPanel — active conversation view.
 *
 * Header: avatar + name + triage pill + next-booking context
 *         + Assign / Star / Info / MoreVertical actions
 * Body: date-separated message bubbles
 * Footer: PresenceStrip → SmartReplyChips → Composer
 *
 * Subscribes to Realtime inserts + presence.
 * Marks conversation read on mount when unread > 0.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { format, isToday, isYesterday, isSameDay } from 'date-fns'
import {
  ChevronLeft,
  MoreVertical,
  Star,
  Archive,
  Info,
  UserCheck,
  Check,
  X,
  AlertCircle,
} from 'lucide-react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Separator } from '@/components/ui/separator'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { MessageBubble } from './MessageBubble'
import { PresenceStrip } from './PresenceStrip'
import { SmartReplyChips } from './SmartReplyChips'
import { Composer } from './Composer'
import { TriageTagPill } from './TriageTagPill'
import { useRealtimeMessages } from '@/hooks/use-realtime-messages'
import { useConversationPresence } from '@/hooks/messages/use-conversation-presence'
import { useSmartReplies } from '@/hooks/messages/use-smart-replies'
import { archiveAction, starAction, resolveAction, unresolveAction, markReadAction } from '@/app/(app)/messages/actions'
import type { ConversationWithClient, ConversationMessage, ConversationContext } from '@/lib/messaging/queries'
import type { MessageTemplate } from '@/lib/supabase/types'
import type { SmartReply } from '@/lib/messaging/triage'

// ─── Types ────────────────────────────────────────────────────────────────────

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

interface ThreadPanelProps {
  conversation: ConversationWithClient
  initialMessages: ConversationMessage[]
  conversationContext: ConversationContext | null
  templates: MessageTemplate[]
  initialSmartReplies: SmartReply[]
  studioId: string
  currentUserId: string
  currentUserName: string
  members: StudioMember[]
  showContextPane: boolean
  onToggleContext: () => void
  showBackButton?: boolean | undefined
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .filter(Boolean)
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function getDayLabel(dateStr: string): string {
  const d = new Date(dateStr)
  if (isToday(d)) return 'Today'
  if (isYesterday(d)) return 'Yesterday'
  return format(d, 'MMMM d, yyyy')
}

// ─── ThreadPanel ──────────────────────────────────────────────────────────────

export function ThreadPanel({
  conversation,
  initialMessages,
  conversationContext,
  templates,
  initialSmartReplies,
  currentUserId,
  currentUserName,
  showContextPane,
  onToggleContext,
  showBackButton = false,
}: ThreadPanelProps) {
  const router = useRouter()
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const composerRef = useRef<{ focus: () => void }>(null)

  const [messages, setMessages] = useState<ConversationMessage[]>(initialMessages)
  const [internalNoteMode, setInternalNoteMode] = useState(false)

  // Smart replies
  const { replies: smartReplies } = useSmartReplies(initialSmartReplies)

  // Presence
  const { viewers, typing } = useConversationPresence(
    conversation.id,
    currentUserId,
    currentUserName,
  )

  const client = conversation.client
  const clientName = client
    ? [client.first_name, client.last_name].filter(Boolean).join(' ')
    : conversation.display_name ?? conversation.external_identifier

  // Mark as read on mount
  useEffect(() => {
    if (conversation.unread_count > 0) {
      void markReadAction(conversation.id).catch(() => void 0)
    }
  }, [conversation.id, conversation.unread_count])

  // Sync messages on navigation
  useEffect(() => {
    setMessages(initialMessages)
  }, [initialMessages])

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages.length])

  // Realtime: append new messages
  const handleNewMessage = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => {
      // Remove matching optimistic message
      const withoutOptimistic = prev.filter((m) => {
        if (!m.id.startsWith('optimistic-')) return true
        return !(
          m.body === msg.body &&
          m.direction === msg.direction &&
          Math.abs(new Date(m.created_at).getTime() - new Date(msg.created_at).getTime()) < 30_000
        )
      })
      if (withoutOptimistic.some((m) => m.id === msg.id)) return withoutOptimistic
      return [...withoutOptimistic, msg]
    })
  }, [])

  useRealtimeMessages(conversation.id, handleNewMessage)

  // Optimistic send
  const handleOptimisticSend = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => [...prev, msg])
  }, [])

  // Quick actions
  const handleArchive = useCallback(async () => {
    const result = await archiveAction(conversation.id)
    if (result.ok) {
      toast.success('Conversation archived')
      router.push('/messages')
    } else {
      toast.error(result.error ?? 'Failed to archive')
    }
  }, [conversation.id, router])

  const handleStar = useCallback(async () => {
    const result = await starAction(conversation.id, !conversation.starred)
    if (result.ok) {
      toast.success(conversation.starred ? 'Removed from starred' : 'Starred')
    } else {
      toast.error(result.error ?? 'Failed')
    }
  }, [conversation.id, conversation.starred])

  const handleResolve = useCallback(async () => {
    const isResolved = !!conversation.resolved_at
    const result = isResolved
      ? await unresolveAction(conversation.id)
      : await resolveAction(conversation.id)

    if (result.ok) {
      toast.success(isResolved ? 'Reopened' : 'Resolved')
    } else {
      toast.error(result.error ?? 'Failed')
    }
  }, [conversation.id, conversation.resolved_at])

  // Group messages by day
  const messageGroups: { dayLabel: string; date: Date; messages: ConversationMessage[] }[] = []
  for (const msg of messages) {
    const d = new Date(msg.created_at)
    const last = messageGroups[messageGroups.length - 1]
    if (!last || !isSameDay(last.date, d)) {
      messageGroups.push({ dayLabel: getDayLabel(msg.created_at), date: d, messages: [msg] })
    } else {
      last.messages.push(msg)
    }
  }

  // Next booking quick context
  const nextBooking = conversationContext?.upcomingBookings?.[0]
  const nextBookingLabel = nextBooking?.scheduled_at
    ? format(new Date(nextBooking.scheduled_at), "EEE h:mm aaa · MMM d")
    : null

  const triageTag = conversation.triage_tag ?? null

  return (
    <div className="flex flex-col h-full min-w-0 bg-background">
      {/* Header */}
      <div className="h-14 px-4 border-b border-border bg-background flex items-center justify-between gap-3 shrink-0">
        {/* Left */}
        <div className="flex items-center gap-3 min-w-0">
          {showBackButton && (
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 shrink-0"
              onClick={() => router.push('/messages')}
              aria-label="Back to conversations"
            >
              <ChevronLeft className="h-4 w-4" aria-hidden />
            </Button>
          )}

          <Avatar className="h-9 w-9 shrink-0">
            <AvatarFallback className="bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground text-xs font-medium">
              {getInitials(clientName)}
            </AvatarFallback>
          </Avatar>

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-bold text-base text-foreground truncate leading-tight">
                {clientName}
              </p>
              {triageTag && <TriageTagPill tag={triageTag} />}
            </div>
            {nextBookingLabel && (
              <p className="text-[11px] text-[color:var(--color-stone)] truncate">
                {nextBookingLabel}
                {nextBooking?.service_name ? ` · ${nextBooking.service_name}` : ''}
              </p>
            )}
          </div>
        </div>

        {/* Right actions */}
        <div className="flex items-center gap-0.5 shrink-0">
          {/* Assign (stub) */}
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                aria-label="Assign conversation"
                className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
              >
                <UserCheck className="h-4 w-4" aria-hidden />
              </button>
            </TooltipTrigger>
            <TooltipContent>Assign</TooltipContent>
          </Tooltip>

          {/* Star */}
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                aria-label={conversation.starred ? 'Unstar' : 'Star'}
                aria-pressed={conversation.starred ?? false}
                onClick={() => void handleStar()}
                className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
              >
                <Star
                  className={cn(
                    'h-4 w-4',
                    conversation.starred && 'fill-[color:var(--color-rust)] text-[color:var(--color-rust)]',
                  )}
                  aria-hidden
                />
              </button>
            </TooltipTrigger>
            <TooltipContent>{conversation.starred ? 'Unstar' : 'Star'}</TooltipContent>
          </Tooltip>

          {/* Info / context pane toggle */}
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                onClick={onToggleContext}
                aria-label={showContextPane ? 'Hide client context' : 'Show client context'}
                aria-pressed={showContextPane}
                className={cn(
                  'h-8 w-8 flex items-center justify-center rounded-md transition-colors',
                  showContextPane
                    ? 'bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground'
                    : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
                )}
              >
                <Info className="h-4 w-4" aria-hidden />
              </button>
            </TooltipTrigger>
            <TooltipContent>{showContextPane ? 'Hide context' : 'Show context'}</TooltipContent>
          </Tooltip>

          {/* More */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button
                type="button"
                aria-label="More actions"
                className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
              >
                <MoreVertical className="h-4 w-4" aria-hidden />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-44">
              <DropdownMenuItem onClick={() => void handleResolve()} className="text-xs">
                {conversation.resolved_at ? (
                  <>
                    <X className="h-3.5 w-3.5 mr-2" aria-hidden />
                    Unresolve
                  </>
                ) : (
                  <>
                    <Check className="h-3.5 w-3.5 mr-2" aria-hidden />
                    Resolve
                  </>
                )}
              </DropdownMenuItem>
              <DropdownMenuItem className="text-xs">
                <AlertCircle className="h-3.5 w-3.5 mr-2" aria-hidden />
                Mark unread
              </DropdownMenuItem>
              {client && (
                <DropdownMenuItem asChild className="text-xs">
                  <Link href={`/clients/${client.id}`}>
                    View client profile
                  </Link>
                </DropdownMenuItem>
              )}
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={() => void handleArchive()}
                className="text-xs text-[color:var(--color-stone)]"
              >
                <Archive className="h-3.5 w-3.5 mr-2" aria-hidden />
                Archive
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Messages area */}
      <ScrollArea className="flex-1 min-h-0">
        <div className="px-4 py-6 space-y-0">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <p className="font-serif italic text-foreground text-base mb-1">No messages yet.</p>
              <p className="text-sm text-[color:var(--color-stone)]">Start the conversation below.</p>
            </div>
          ) : (
            messageGroups.map((group) => (
              <div key={group.dayLabel}>
                {/* Day separator */}
                <div className="flex items-center gap-3 my-4">
                  <Separator className="flex-1" />
                  <span className="text-[11px] text-[color:var(--color-stone)] font-medium whitespace-nowrap px-1">
                    {group.dayLabel}
                  </span>
                  <Separator className="flex-1" />
                </div>

                {/* Messages in this day */}
                {group.messages.map((msg, i) => {
                  const prev = group.messages[i - 1]
                  const isGrouped =
                    !!prev &&
                    prev.direction === msg.direction &&
                    prev.is_internal_note === msg.is_internal_note
                  return <MessageBubble key={msg.id} message={msg} isGrouped={isGrouped} />
                })}
              </div>
            ))
          )}
          <div ref={messagesEndRef} />
        </div>
      </ScrollArea>

      {/* Presence strip */}
      <PresenceStrip viewers={viewers} typing={typing} />

      {/* Smart reply chips */}
      {client && smartReplies.length > 0 && (
        <SmartReplyChips
          replies={smartReplies}
          conversationId={conversation.id}
          clientId={client.id}
          channel={conversation.channel === 'email' ? 'email' : 'sms'}
        />
      )}

      {/* Composer */}
      <Composer
        conversationId={conversation.id}
        clientId={client?.id ?? ''}
        channel={conversation.channel as 'sms' | 'email' | 'instagram' | 'whatsapp' | 'webchat' | 'phone'}
        clientFirstName={client?.first_name}
        clientHasPhone={!!client?.phone}
        clientHasEmail={!!client?.email}
        templates={templates}
        onOptimisticSend={handleOptimisticSend}
        onInternalNoteModeChange={setInternalNoteMode}
        disabled={!client}
      />

      {!client && (
        <p className="text-center text-xs text-[color:var(--color-stone)] px-4 py-1.5 bg-[color-mix(in_srgb,var(--color-stone)_8%,transparent)] border-t border-border">
          Link this conversation to a client before sending messages.
        </p>
      )}
    </div>
  )
}

'use client'

/**
 * MessagesShell — 3-pane omnichannel inbox shell.
 *
 * Desktop ≥1280px:  rail(72) | list(360) | thread(1fr) | context(380, toggleable)
 * Tablet 1024-1279: same grid but context renders as Sheet
 * Mobile <1024:     stacked — channel rail as horizontal strip, list or thread only
 *
 * All layout state lives here. Data is passed from the server page.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { useMessagesShortcuts } from '@/hooks/messages/use-messages-shortcuts'
import { useIsMobile } from '@/hooks/useIsMobile'
import { ChannelRail } from './ChannelRail'
import { ConversationList } from './ConversationList'
import { ThreadPanel } from './ThreadPanel'
import { ContextPane } from './ContextPane'
import { MessagesHeader } from './MessagesHeader'
import { ShortcutCheatsheet } from './ShortcutCheatsheet'
import type {
  ConversationWithClient,
  ConversationMessage,
  ConversationContext,
  MessageTemplate,
  Channel,
} from '@/lib/messaging/queries'
import type { SmartReply } from '@/lib/messaging/triage'

// ─── Types ────────────────────────────────────────────────────────────────────

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

export interface MessagesShellProps {
  conversations: ConversationWithClient[]
  activeConversation: ConversationWithClient | null
  activeMessages: ConversationMessage[]
  conversationContext: ConversationContext | null
  templates: MessageTemplate[]
  unreadCounts: Record<Channel, number>
  studioId: string
  activeConversationId: string | null
  searchParams: { c?: string | undefined; channel?: string | undefined; filter?: string | undefined; q?: string | undefined }
  currentUserId: string
  currentUserName: string
  members: StudioMember[]
  smartReplies: SmartReply[]
}

// ─── useIsWide (≥1280px) ──────────────────────────────────────────────────────

function useIsWide(): boolean {
  const [isWide, setIsWide] = useState(false)

  useEffect(() => {
    function update() {
      setIsWide(window.innerWidth >= 1280)
    }
    update()
    const mql = window.matchMedia('(min-width: 1280px)')
    mql.addEventListener('change', update)
    return () => mql.removeEventListener('change', update)
  }, [])

  return isWide
}

function useIsTablet(): boolean {
  const [isTablet, setIsTablet] = useState(false)

  useEffect(() => {
    function update() {
      const w = window.innerWidth
      setIsTablet(w >= 1024 && w < 1280)
    }
    update()
    const mql = window.matchMedia('(min-width: 1024px) and (max-width: 1279px)')
    mql.addEventListener('change', update)
    return () => mql.removeEventListener('change', update)
  }, [])

  return isTablet
}

// ─── MessagesShell ─────────────────────────────────────────────────────────────

export function MessagesShell({
  conversations,
  activeConversation,
  activeMessages,
  conversationContext,
  templates,
  unreadCounts,
  studioId,
  activeConversationId,
  searchParams,
  currentUserId,
  currentUserName,
  members,
  smartReplies,
}: MessagesShellProps) {
  const isMobile = useIsMobile()
  const isWide = useIsWide()
  const isTablet = useIsTablet()

  const [showContext, setShowContext] = useState(false)
  const [showCheatsheet, setShowCheatsheet] = useState(false)

  const currentChannel = searchParams.channel ?? null

  // Keyboard shortcuts
  const handleToggleInternalNote = useCallback(() => {
    // Raise to composer via internalNoteMode — toggled at composer level via shortcut
    // For now: noop (composer handles its own state)
  }, [])

  useMessagesShortcuts({
    onFocusSearch: useCallback(() => {
      const el = document.querySelector<HTMLInputElement>('[aria-label="Search conversations"]')
      el?.focus()
    }, []),
    onNavigateDown: useCallback(() => {
      // Implemented in ConversationList via keyboard events
    }, []),
    onNavigateUp: useCallback(() => {
      // Implemented in ConversationList via keyboard events
    }, []),
    onFocusComposer: useCallback(() => {
      const el = document.querySelector<HTMLTextAreaElement>('[aria-label="Message body"]') ??
        document.querySelector<HTMLTextAreaElement>('[aria-label="Internal note body"]')
      el?.focus()
    }, []),
    onAssign: useCallback(() => void 0, []),
    onArchive: useCallback(() => void 0, []),
    onStar: useCallback(() => void 0, []),
    onToggleInternalNote: handleToggleInternalNote,
    onShowCheatsheet: useCallback(() => setShowCheatsheet(true), []),
    onClose: useCallback(() => setShowContext(false), []),
  })

  // ── Mobile layout ──────────────────────────────────────────────────────────
  if (isMobile) {
    if (activeConversation) {
      return (
        <div className="flex flex-col h-full">
          <MessagesHeader
            unreadCounts={unreadCounts}
            onShowCheatsheet={() => setShowCheatsheet(true)}
          />
          <div className="flex-1 min-h-0">
            <ThreadPanel
              conversation={activeConversation}
              initialMessages={activeMessages}
              conversationContext={conversationContext}
              templates={templates}
              initialSmartReplies={smartReplies}
              studioId={studioId}
              currentUserId={currentUserId}
              currentUserName={currentUserName}
              members={members}
              showContextPane={false}
              onToggleContext={() => setShowContext(true)}
              showBackButton
            />
          </div>
          {conversationContext && (
            <ContextPane
              context={conversationContext}
              conversationId={activeConversationId ?? ''}
              onClose={() => setShowContext(false)}
              renderAsSheet
              sheetOpen={showContext}
            />
          )}
          <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
        </div>
      )
    }

    return (
      <div className="flex flex-col h-full">
        <MessagesHeader
          unreadCounts={unreadCounts}
          onShowCheatsheet={() => setShowCheatsheet(true)}
        />
        {/* Horizontal channel strip */}
        <div className="flex overflow-x-auto border-b border-border bg-background shrink-0 px-2 py-1 gap-1">
          {(['all', 'sms', 'email', 'instagram', 'whatsapp', 'webchat', 'phone'] as const).map(
            (ch) => {
              const isActive = ch === (currentChannel ?? 'all')
              return (
                <button
                  key={ch}
                  type="button"
                  className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-[0.08em] shrink-0 transition-colors ${
                    isActive
                      ? 'bg-primary text-primary-foreground'
                      : 'text-[color:var(--color-stone)] hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]'
                  }`}
                >
                  {ch === 'all' ? 'ALL' : ch.toUpperCase()}
                </button>
              )
            },
          )}
        </div>
        <div className="flex-1 min-h-0 overflow-hidden">
          <ConversationList
            conversations={conversations}
            studioId={studioId}
            activeConversationId={activeConversationId}
          />
        </div>
        <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
      </div>
    )
  }

  // ── Desktop / Tablet layout ────────────────────────────────────────────────
  // Context pane: grid col on wide, sheet on tablet
  const contextIsSheet = isTablet && !isWide
  const showContextPane = showContext && !!activeConversation && !!conversationContext

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Top header */}
      <MessagesHeader
        unreadCounts={unreadCounts}
        onShowCheatsheet={() => setShowCheatsheet(true)}
      />

      {/* 3/4-pane grid */}
      <div
        className="flex-1 min-h-0 grid overflow-hidden transition-[grid-template-columns] duration-150 ease-out"
        style={{
          gridTemplateColumns:
            showContextPane && !contextIsSheet
              ? '72px 360px minmax(0,1fr) 380px'
              : '72px 360px minmax(0,1fr)',
        }}
      >
        {/* Rail */}
        <ChannelRail
          unreadCounts={unreadCounts}
          currentChannel={currentChannel}
        />

        {/* List */}
        <ConversationList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />

        {/* Thread panel */}
        {activeConversation ? (
          <ThreadPanel
            conversation={activeConversation}
            initialMessages={activeMessages}
            conversationContext={conversationContext}
            templates={templates}
            initialSmartReplies={smartReplies}
            studioId={studioId}
            currentUserId={currentUserId}
            currentUserName={currentUserName}
            members={members}
            showContextPane={showContextPane}
            onToggleContext={() => setShowContext((v) => !v)}
          />
        ) : (
          <EmptyThreadState hasConversations={conversations.length > 0} />
        )}

        {/* Context pane (grid col — desktop only) */}
        {showContextPane && !contextIsSheet && conversationContext && (
          <ContextPane
            context={conversationContext}
            conversationId={activeConversationId ?? ''}
            onClose={() => setShowContext(false)}
          />
        )}
      </div>

      {/* Context pane as sheet (tablet) */}
      {contextIsSheet && conversationContext && (
        <ContextPane
          context={conversationContext}
          conversationId={activeConversationId ?? ''}
          onClose={() => setShowContext(false)}
          renderAsSheet
          sheetOpen={showContextPane}
        />
      )}

      <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
    </div>
  )
}

// ─── EmptyThreadState ─────────────────────────────────────────────────────────

function EmptyThreadState({ hasConversations }: { hasConversations: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center h-full text-center px-8 bg-background">
      <h2 className="font-serif italic text-foreground text-xl mb-2">
        {hasConversations ? 'Select a conversation.' : 'No messages yet.'}
      </h2>
      <p className="text-sm text-[color:var(--color-stone)] max-w-xs">
        {hasConversations
          ? 'Choose a conversation from the list to view messages.'
          : 'When clients message you via SMS or email, conversations will appear here.'}
      </p>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getConversationContext,
  getChannelUnreadCounts,
  listMessageTemplates,
  type ListConversationsFilters,
  type ConversationContext,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { generateSmartReplies } from '@/lib/messaging/triage'
import { MessagesShell } from '@/components/messages/MessagesShell'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

// Next 16 — searchParams must be awaited
interface SearchParams {
  c?: string
  channel?: string
  filter?: string
  q?: string
}

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

export default async function MessagesPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const params = await searchParams
  const activeConversationId = params.c ?? null
  const channelFilter = params.channel ?? null
  const filterParam = params.filter ?? null
  const searchQuery = params.q ?? null

  // Get current user for presence
  const authUser = await getAuthenticatedUser()
  const currentUserId = authUser?.user.id ?? ''
  const currentUserName = authUser?.user.full_name ?? 'Team member'

  // Resolve 'assigned-to-me' filter
  let resolvedAssignedTo: string | undefined
  if (filterParam === 'assigned-to-me') {
    resolvedAssignedTo = currentUserId || undefined
  }

  // Build filters object — only include defined optional props (exactOptionalPropertyTypes)
  const convFilters: ListConversationsFilters = {
    limit: 50,
    archived: filterParam === 'archived',
    unreadOnly: filterParam === 'unread',
  }
  if (filterParam === 'starred') convFilters.starred = true
  if (filterParam === 'resolved') convFilters.resolved = true
  if (channelFilter) {
    convFilters.channel = channelFilter as ListConversationsFilters['channel']
  }
  if (searchQuery) convFilters.search = searchQuery
  if (resolvedAssignedTo) convFilters.assignedTo = resolvedAssignedTo

  // Parallel fetch: conversation list + channel unread counts + templates + studio members
  const [listResult, unreadCounts, templates, membersResult] = await Promise.all([
    listConversations(studioId, convFilters),
    getChannelUnreadCounts(studioId),
    listMessageTemplates(studioId),
    (async (): Promise<StudioMember[]> => {
      try {
        const supabase = await createClient()
        const { data } = await supabase
          .from('studio_members')
          .select('id, user_id, role')
          .eq('studio_id', studioId)
          .is('deactivated_at', null)
        return (data ?? []) as StudioMember[]
      } catch {
        return []
      }
    })(),
  ])

  const { conversations } = listResult

  // Fetch active conversation data if c= param is set
  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let conversationContext: ConversationContext | null = null
  let smartReplies: Awaited<ReturnType<typeof generateSmartReplies>> = []

  if (activeConversationId) {
    // Parallel fetch: conversation + messages + context pane data
    const [conv, msgs, ctx] = await Promise.all([
      getConversation(studioId, activeConversationId),
      getConversationMessages(studioId, activeConversationId, { limit: 50 }),
      getConversationContext(studioId, activeConversationId),
    ])

    activeConversation = conv
    activeMessages = msgs
    conversationContext = ctx

    // Mark as read if unread
    if (activeConversation && activeConversation.unread_count > 0) {
      await markConversationRead(studioId, activeConversationId)
    }

    // Generate smart replies for active conversation
    if (activeConversation && ctx) {
      const lastInbound =
        [...msgs].reverse().find((m) => m.direction === 'inbound') ?? null
      try {
        smartReplies = await generateSmartReplies({
          conversation: activeConversation,
          lastInboundMessage: lastInbound,
          upcomingBookings: ctx.upcomingBookings,
        })
      } catch {
        smartReplies = []
      }
    }
  }

  return (
    <div className="h-full flex flex-col overflow-hidden">
      <MessagesShell
        conversations={conversations}
        activeConversation={activeConversation}
        activeMessages={activeMessages}
        studioId={studioId}
        activeConversationId={activeConversationId}
        templates={templates}
        conversationContext={conversationContext}
        unreadCounts={unreadCounts}
        searchParams={params}
        currentUserId={currentUserId}
        currentUserName={currentUserName}
        members={membersResult}
        smartReplies={smartReplies}
      />
    </div>
  )
}

